theorem ProbabilityTheory.IsUniform.extracted_1.{uT, uS, uΩ} {Ω : Type uΩ} {S : Type uS} {T : Type uT}
  [mΩ : MeasurableSpace Ω] {X : Ω → S} {μ : Measure Ω} {H : Finset S} (h : IsUniform (↑H) X μ) {f : S → T}
  (hf : Injective f) (x : S) (hx : x ∈ H) (y : S) (hy : y ∈ H) (A : ∀ (z : S), f ⁻¹' {f z} = {z}) :
  μ (f ∘ X ⁻¹' {f x}) = μ (f ∘ X ⁻¹' {f y}) := by
  simp [preimage_comp, A, h.eq_of_mem hx hy]

theorem ProbabilityTheory.IsUniform.extracted_1.{uT, uS, uΩ} {Ω : Type uΩ} {S : Type uS} {T : Type uT}
  [mΩ : MeasurableSpace Ω] {X : Ω → S} {μ : Measure Ω} {H : Finset S} (h : IsUniform (↑H) X μ) {f : S → T}
  (hf : Injective f) (x : S) (hx : x ∈ H) (y : S) (hy : y ∈ H) (z : S) : f ⁻¹' {f z} = {z} := by
  ext; simp [hf.eq_iff]

